import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"ADR-016: Keep 9:16 as the only format for 1.0; square, portrait and landscape on the roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"adr/016-vertical-only-formats.md","filePath":"adr/016-vertical-only-formats.md"}'),s={name:"adr/016-vertical-only-formats.md"};function n(l,e,i,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-016-keep-9-16-as-the-only-format-for-1-0-square-portrait-and-landscape-on-the-roadmap" tabindex="-1">ADR-016: Keep 9:16 as the only format for 1.0; square, portrait and landscape on the roadmap <a class="header-anchor" href="#adr-016-keep-9-16-as-the-only-format-for-1-0-square-portrait-and-landscape-on-the-roadmap" aria-label="Permalink to &quot;ADR-016: Keep 9:16 as the only format for 1.0; square, portrait and landscape on the roadmap&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-11-01</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Requests for square (1080×1080), 4:5 portrait (1080×1350) and 16:9 landscape (1920×1080) output came up while preparing the open-source release. Presets already describe the canvas, the header, the stage band and the platform safe zones in YAML (<code>presets/*.preset.yaml</code>), so a new preset looks cheap. It is not, because of how element geometry works:</p><ul><li>Every element is placed in <strong>absolute stage coordinates</strong>: a 1080 × 1000 box between the header (y 270) and the captions (y 1300). Episodes, templates, blueprints, skills, the editor&#39;s guides and the V-6/V-7/V-8 checks all assume that box.</li><li>A square or 4:5 canvas has 1080 or 1350 px of height for header, stage and captions together; the stage would shrink to roughly 600–850 px. Existing layouts would overflow or overlap (V-6, V-8), and texts sized for 1000 px would no longer fit (V-9).</li><li>A landscape canvas changes the aspect of the stage itself (wide, not tall). Diagrams laid out as columns would need to become rows; no uniform scale keeps them readable.</li></ul><p>Doing this properly means a <strong>relative layout model</strong> (anchors, flow or grid placement, or per-format <code>place</code> overrides) across the compiler, runtime, editor, lint rules, templates and every example: a rewrite of the layout contract, not a preset.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>ReelForge 1.0 ships <strong>9:16 only</strong> (<code>tiktok</code>, <code>reels</code>, <code>shorts</code>). Additional formats are on the roadmap behind a relative placement model, designed in a separate ADR before any code. Until then, people who need another format can render 9:16 and crop or pad with ffmpeg, accepting that the layout is not adapted.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The Timeline contract and golden frames stay stable for the first release.</li><li>Templates, blueprints and skills can keep using fixed, tested coordinates, which is what makes them reliable for small models.</li><li>The roadmap item is explicit: relative placement first (likely <code>place: { anchor, w%, h% }</code> with per-preset resolution in the compiler), then square, 4:5 and 16:9 presets with their own safe zones.</li></ul>',10)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
